// C dependencies supplied by the surrounding kernel CIFS implementation are
// intentionally referenced but not defined in this isolated translation.

/* Automatically generated by the `gen_smb2_mapping` script. */
extern "C" {
    static smb2_error_map_table: [status_to_posix_error; 0];
}

unsafe fn cmp_smb2_status(key: *const core::ffi::c_void,
                          pivot: *const core::ffi::c_void) -> i32 {
    let key = *(key as *const u32);
    let pivot = &*(pivot as *const status_to_posix_error);

    if key < pivot.smb2_status {
        return -1;
    }
    if key > pivot.smb2_status {
        return 1;
    }
    0
}

unsafe fn smb2_get_err_map(smb2_status: u32) -> *const status_to_posix_error {
    let err_map: *const status_to_posix_error;

    err_map = __inline_bsearch(
        &smb2_status as *const u32 as *const core::ffi::c_void,
        smb2_error_map_table.as_ptr() as *const core::ffi::c_void,
        smb2_error_map_table.len(),
        core::mem::size_of::<status_to_posix_error>(),
        cmp_smb2_status,
    );
    err_map
}

pub unsafe fn map_smb2_to_linux_error(buf: *mut i8, mut log_err: bool) -> i32 {
    let shdr = buf as *mut smb2_hdr;
    let mut rc: i32 = -EIO;
    let smb2err: __le32 = (*shdr).Status;
    let err_map: *const status_to_posix_error;

    if smb2err == 0 {
        trace_smb3_cmd_done(
            le32_to_cpu((*shdr).Id.SyncId.TreeId),
            le64_to_cpu((*shdr).SessionId),
            le16_to_cpu((*shdr).Command),
            le64_to_cpu((*shdr).MessageId),
        );
        return 0;
    }

    log_err = (log_err && (smb2err != STATUS_MORE_PROCESSING_REQUIRED)
        && (smb2err != STATUS_END_OF_FILE)) || (cifsFYI & CIFS_RC) != 0;

    err_map = smb2_get_err_map(le32_to_cpu(smb2err));
    if err_map.is_null() {
        return map_smb2_to_linux_error_out(shdr, smb2err, rc, log_err);
    }

    rc = (*err_map).posix_error;
    if log_err {
        pr_notice!(
            "Status code returned 0x{:08x} {}\n",
            (*err_map).smb2_status,
            (*err_map).status_string,
        );
    }

    map_smb2_to_linux_error_out(shdr, smb2err, rc, log_err)
}

unsafe fn map_smb2_to_linux_error_out(
    shdr: *mut smb2_hdr,
    smb2err: __le32,
    rc: i32,
    _log_err: bool,
) -> i32 {
    // On error mapping not found, return EIO.
    cifs_dbg!(
        FYI,
        "Mapping SMB2 status code 0x{:08x} to POSIX err {}\n",
        le32_to_cpu(smb2err),
        rc,
    );

    trace_smb3_cmd_err(
        le32_to_cpu((*shdr).Id.SyncId.TreeId),
        le64_to_cpu((*shdr).SessionId),
        le16_to_cpu((*shdr).Command),
        le64_to_cpu((*shdr).MessageId),
        le32_to_cpu(smb2err),
        rc,
    );
    if rc == -EIO {
        smb_EIO1(smb_eio_trace_smb2_received_error, le32_to_cpu(smb2err));
    }
    rc
}

pub unsafe fn smb2_init_maperror() -> i32 {
    let mut i: usize = 1;

    // Check whether the array is sorted in ascending order.
    while i < smb2_error_map_table.len() {
        if smb2_error_map_table[i].smb2_status
            >= smb2_error_map_table[i - 1].smb2_status
        {
            i += 1;
            continue;
        }

        pr_err!("smb2_error_map_table array order is incorrect\n");
        return -EINVAL;
    }

    0
}

// Preserved build-time condition: CONFIG_SMB_KUNIT_TESTS.
#[cfg(CONFIG_SMB_KUNIT_TESTS)]
pub unsafe fn smb2_get_err_map_test(smb2_status: u32) -> *const status_to_posix_error {
    smb2_get_err_map(smb2_status)
}

#[cfg(CONFIG_SMB_KUNIT_TESTS)]
pub static smb2_error_map_table_test: *const status_to_posix_error = unsafe {
    smb2_error_map_table.as_ptr()
};

#[cfg(CONFIG_SMB_KUNIT_TESTS)]
pub static smb2_error_map_num: usize = unsafe { smb2_error_map_table.len() };

